 Texture2D? CombatTexture(Unit u){if(u.Role==Role.Robot)return robotCombatPortrait;if(EnemyAtlasCell(u.Role,out var column,out var row)){var size=enemyAtlas.GetSize();return new AtlasTexture{Atlas=enemyAtlas,Region=new Rect2(column*size.X/3f,row*size.Y/2f,size.X/3f,size.Y/2f)};}if(portraits.TryGetValue(u.Id,out var face))return face;var key=u.Id=="nance"&&u.Bear?"nance-bear":u.Id;return boardTokens.TryGetValue(key,out var token)?token:null;}
 List<Cell> EnemyVisualPath(Cell start,Cell goal){if(start==goal)return[start];var previous=new Dictionary<Cell,Cell>();var seen=new HashSet<Cell>{start};var queue=new Queue<Cell>();queue.Enqueue(start);while(queue.TryDequeue(out var cell)){foreach(var next in cell.Neighbors()){if(!b.Floor(next)||seen.Contains(next)||(b.At(next)!=null&&next!=goal))continue;seen.Add(next);previous[next]=cell;if(next==goal){var path=new List<Cell>{goal};var step=goal;while(step!=start){step=previous[step];path.Add(step);}path.Reverse();return path;}queue.Enqueue(next);}}return[start,goal];}
 void BeginEnemyPresentation(Unit enemy){activeActingUnit=enemy;var start=enemy.Position;var before=b.Units.ToDictionary(u=>u.Id,u=>(u.Hp,u.Captured));var logStart=b.Log.Count;b.Enemy(enemy);var finish=enemy.Position;enemyMovePath=b.LastMovePath.ToList();if(enemyMovePath.Count>1)PlaySfx(enemy.Role is Role.Droid or Role.HeavyDroid or Role.OmpokProxy or Role.SynapticEngineer?"droid_move":"footstep");animatedEnemyCell=new Vector2(start.X,start.Y);combatTarget=b.Units.FirstOrDefault(u=>before.TryGetValue(u.Id,out var old)&&(u.Hp<old.Hp||u.Captured&&!old.Captured));if(combatTarget!=null){var old=before[combatTarget.Id];combatTargetHpBefore=old.Hp;combatTargetCapturedBefore=old.Captured;}enemyActionText=b.Log.Skip(logStart).FirstOrDefault(line=>line.StartsWith(enemy.Name+":"))??b.Log.Skip(logStart).FirstOrDefault()??$"{enemy.Name} acts.";enemyPresentationTimer=0;enemyPresentationStage=enemyMovePath.Count>1?1:2;Refresh();if(enemyPresentationStage==2)ShowEnemyCombatOrPause();}
 bool BeginPlayerMove(Unit actor,Cell destination){if(enemyPresentationStage>0)return false;var start=actor.Position;if(!b.Move(actor,destination))return false;PlaySfx(actor.Role is Role.Robot or Role.Droid or Role.HeavyDroid?"droid_move":"footstep");playerPresentation=true;activeActingUnit=actor;combatTarget=null;enemyMovePath=b.LastMovePath.ToList();animatedEnemyCell=new Vector2(start.X,start.Y);enemyActionText=$"{actor.Name} moved.";enemyPresentationTimer=0;enemyPresentationStage=enemyMovePath.Count>1?1:3;Refresh();return true;}
 bool BeginPlayerUndo(Unit actor){if(enemyPresentationStage>0)return false;var start=actor.Position;if(!b.UndoMove(actor))return false;playerPresentation=true;activeActingUnit=actor;combatTarget=null;enemyMovePath=b.LastMovePath.ToList();animatedEnemyCell=new Vector2(start.X,start.Y);enemyActionText=$"{actor.Name} reconsidered the move.";enemyPresentationTimer=0;enemyPresentationStage=enemyMovePath.Count>1?1:3;Refresh();return true;}
 bool BeginPlayerAttack(Unit actor,Unit target,int weaponIndex){if(enemyPresentationStage>0)return false;var oldHp=target.Hp;var oldCaptured=target.Captured;var logStart=b.Log.Count;if(!b.Attack(actor,target,weaponIndex))return false;playerPresentation=true;activeActingUnit=actor;combatTarget=target;enemyMovePath=[actor.Position];animatedEnemyCell=new Vector2(actor.Position.X,actor.Position.Y);combatTargetHpBefore=oldHp;combatTargetCapturedBefore=oldCaptured;enemyActionText=b.Log.Skip(logStart).FirstOrDefault(line=>line.StartsWith(actor.Name+":"))??b.Log.Skip(logStart).FirstOrDefault()??$"{actor.Name} attacks.";enemyPresentationTimer=0;enemyPresentationStage=2;Refresh();ShowEnemyCombatOrPause();return true;}
 bool BeginPlayerInteract(Unit actor){if(enemyPresentationStage>0)return false;var target=!b.ConsoleUsed&&actor.Position.Distance(b.Console)<=1?b.Units.Where(x=>x.Alive&&x.Team==Team.Enemy).OrderBy(x=>x.Position.Distance(b.Console)).FirstOrDefault():null;var logStart=b.Log.Count;if(!b.Interact(actor))return false;PlaySfx(target!=null?"door_console":"rescue");if(target==null)return true;playerPresentation=true;activeActingUnit=actor;combatTarget=target;enemyMovePath=[actor.Position];animatedEnemyCell=new Vector2(actor.Position.X,actor.Position.Y);enemyActionText=b.Log.Skip(logStart).LastOrDefault()??$"{actor.Name} activated the console.";enemyCombatImage.Texture=CombatTexture(actor);targetCombatImage.Texture=CombatTexture(target);enemyCombatVersus.Text="DISABLES";enemyCombatTitle.Text="CONSOLE ACTIVATED";enemyCombatTitle.AddThemeColorOverride("font_color",new Color("55e6ff"));enemyCombatResult.Text=$"{enemyActionText}\n\n{target.Name.ToUpper()} IS STUNNED FOR ITS NEXT TURN\n\nCLICK TO CONTINUE";enemyCombatPanel.Visible=true;enemyPresentationStage=2;enemyPresentationTimer=0;Refresh();return true;}
 void ShowEnemyCombatOrPause(){animatedEnemyCell=activeActingUnit==null?null:new Vector2(activeActingUnit.Position.X,activeActingUnit.Position.Y);if(activeActingUnit!=null&&combatTarget!=null){PlayAttackSfx(activeActingUnit,enemyActionText);var struck=combatTarget;var tookDamage=combatTargetHpBefore>struck.Hp;if(tookDamage)GetTree().CreateTimer(.24).Timeout+=()=>{impactPlayer.Stream=sfx[struck.Alive?"damage_hit":"unit_defeat"];impactPlayer.Play();};enemyCombatImage.Texture=CombatTexture(activeActingUnit);targetCombatImage.Texture=CombatTexture(combatTarget);enemyCombatVersus.Text="ATTACKS";enemyCombatTitle.Text=$"{activeActingUnit.Name.ToUpper()} ATTACKS {combatTarget.Name.ToUpper()}";enemyCombatTitle.AddThemeColorOverride("font_color",activeActingUnit.Team==Team.Player?new Color("55e6ff"):new Color("ff9b8f"));var resultText=combatTarget.Captured&&!combatTargetCapturedBefore?"CAPTURED":combatTargetHpBefore==combatTarget.Hp?"STUNNED":$"{combatTargetHpBefore-combatTarget.Hp} DAMAGE   •   {combatTarget.Hp}/{combatTarget.MaxHp} HP";if(!combatTarget.Alive)resultText+="   •   DEFEATED";enemyCombatResult.Text=$"{enemyActionText}\n{resultText}\n\nCLICK TO CONTINUE";enemyCombatPanel.Visible=true;enemyPresentationStage=2;enemyPresentationTimer=0;}else if(activeActingUnit!=null&&enemyMovePath.Count==1){enemyCombatImage.Texture=CombatTexture(activeActingUnit);targetCombatImage.Texture=null;enemyCombatVersus.Text="ACTS";enemyCombatTitle.Text=$"{activeActingUnit.Name.ToUpper()} · {(activeActingUnit.Team==Team.Player?"CREW ACTION":"ENEMY ACTION")}";enemyCombatResult.Text=$"{enemyActionText}\n\nCLICK TO CONTINUE";enemyCombatPanel.Visible=true;enemyPresentationStage=2;enemyPresentationTimer=0;}else{enemyPresentationStage=3;enemyPresentationTimer=.38;}}
 void FinishEnemyPresentation(){var wasPlayer=playerPresentation;playerPresentation=false;enemyCombatPanel.Visible=false;activeActingUnit=null;combatTarget=null;animatedEnemyCell=null;enemyMovePath.Clear();enemyPresentationStage=0;timer=.18;Refresh();if(wasPlayer){SelectNextReady();Refresh();MaybeAutoEnd();}}
 void UpdateEnemyPresentation(double delta){if(enemyPresentationStage==1){enemyPresentationTimer+=delta;const double stepDuration=.22;var segment=(int)(enemyPresentationTimer/stepDuration);if(segment>=enemyMovePath.Count-1){ShowEnemyCombatOrPause();}else{var amount=(float)((enemyPresentationTimer-segment*stepDuration)/stepDuration);var from=enemyMovePath[segment];var to=enemyMovePath[segment+1];animatedEnemyCell=new Vector2(from.X,from.Y).Lerp(new Vector2(to.X,to.Y),amount);QueueRedraw();}}else if(enemyPresentationStage==3){enemyPresentationTimer-=delta;if(enemyPresentationTimer<=0)FinishEnemyPresentation();}}
