  var displayLabel=new Label{Text="WINDOW SIZE",CustomMinimumSize=new(0,28)};displayLabel.AddThemeFontSizeOverride("font_size",17);box.AddChild(displayLabel);var display=new OptionButton{CustomMinimumSize=new(0,48)};foreach(var choice in new[]{"Compact  ·  1120 × 856","Standard  ·  1400 × 1070","Large  ·  1680 × 1284","Fullscreen"})display.AddItem(choice);display.Selected=settings.DisplayMode switch{"Compact"=>0,"Large"=>2,"Fullscreen"=>3,_=>1};display.ItemSelected+=index=>{settings.DisplayMode=index switch{0=>"Compact",2=>"Large",3=>"Fullscreen",_=>"Standard"};GameSettingsStorage.Save(settings);GameSettingsStorage.ApplyDisplay(settings.DisplayMode);};box.AddChild(display);
  var tutorialToggle=new CheckBox{Text="Captain Jeane tutorial",ButtonPressed=settings.Tutorial,CustomMinimumSize=new(0,48)};tutorialToggle.AddThemeFontSizeOverride("font_size",17);tutorialToggle.Toggled+=enabled=>{settings.Tutorial=enabled;if(!enabled)tutorialPanel.Visible=false;GameSettingsStorage.Save(settings);};box.AddChild(tutorialToggle);
