 void ShowFeedback(){landingMenu.Visible=false;feedbackStatus.Text="";feedbackPanel.Visible=true;feedbackMessage.GrabFocus();}
 string FeedbackType()=>feedbackKind.GetItemText(feedbackKind.Selected);
 string FeedbackContext()=>CampaignSummary().Replace("\n"," — ");
 void SaveFeedback(){if(string.IsNullOrWhiteSpace(feedbackMessage.Text)){feedbackStatus.AddThemeColorOverride("font_color",new("ef8790"));feedbackStatus.Text="Please write a message before saving.";return;}FeedbackStorage.Save(FeedbackType(),feedbackSubject.Text,feedbackMessage.Text,FeedbackContext());feedbackStatus.AddThemeColorOverride("font_color",new("8fe3a1"));feedbackStatus.Text="Feedback saved. Thank you!";feedbackSubject.Text="";feedbackMessage.Text="";}
