 void AddVolumeSetting(VBoxContainer parent,string name,float value,Action<double> changed){var row=new HBoxContainer();row.AddThemeConstantOverride("separation",14);var label=new Label{Text=$"{name.ToUpper()}   {Mathf.RoundToInt(value*100)}%",CustomMinimumSize=new(235,40),VerticalAlignment=VerticalAlignment.Center};label.AddThemeFontSizeOverride("font_size",17);row.AddChild(label);var slider=new HSlider{MinValue=0,MaxValue=1,Step=.05,Value=value,CustomMinimumSize=new(380,40)};slider.ValueChanged+=v=>{label.Text=$"{name.ToUpper()}   {Mathf.RoundToInt(v*100)}%";changed(v);};row.AddChild(slider);parent.AddChild(row);}
