 void StartMission2(){var c=b.Campaign;CampaignStorage.Save(c);b=new(b.Mission==2?3:2,c);rosterReady=false;selected=b.Units.First(u=>u.Role==Role.Officer);mode="move";PlayBattleMusic();Refresh();}
 void ChooseUpgrade(int choice){var c=b.Campaign;if(upgradeStep==0)c.XanderUpgrade=choice==0?"Marksman":"Skirmisher";else if(upgradeStep==1)c.NanceUpgrade=choice==0?"Iron Bear":"Enduring Bear";else if(upgradeStep==2)c.AkikoUpgrade=choice==0?"Hardened Robots":"Field Tech";else c.IssacUpgrade=choice==0?"Combat Training":"Master Mechanic";upgradeStep++;if(upgradeStep>=4){rosterReady=true;CampaignStorage.Save(c);}Refresh();}
 void Button(string text,Action run,bool enabled=true){var tip=ActionTip(text);var x=new Button{Text=text,TooltipText="",Disabled=!enabled,CustomMinimumSize=new(0,27)};x.MouseEntered+=()=>ShowHelp(tip);x.MouseExited+=ClearHelp;x.Pressed+=()=>{run();SelectNextReady();Refresh();MaybeAutoEnd();};actions.AddChild(x);}
 string DefaultHelp()=>"HOVER HELP  •  Point to a portrait, attack, or ability to see what it does.";
 void ShowHelp(string text){hoverHelpText.Text=text;}
 void ClearHelp(){hoverHelpText.Text=DefaultHelp();}
 void ResetTutorial(){tutorialLessons.Clear();tutorialLesson="";tutorialUnit="";if(tutorialPanel!=null)tutorialPanel.Visible=false;}
 void CompleteTutorialLesson(){
  if(tutorialLesson=="")return;
  bool done=tutorialLesson switch{"move"=>b.Units.Any(u=>u.Team==Team.Player&&u.Moved),"high-ground"=>b.Units.Any(u=>u.Id==tutorialUnit&&u.Moved),"low-cover"=>b.Units.Any(u=>u.Id==tutorialUnit&&u.Acted),"nance"=>b.Units.Any(u=>u.Id=="nance"&&u.Bear),"akiko"=>b.Robots>0,"attack"=>b.Units.Any(u=>u.Id==tutorialUnit&&u.Acted),"console"=>b.ConsoleUsed,"rescue"=>b.Finished&&b.Phase==Phase.Victory,_=>false};
  if(done){tutorialLessons.Add(tutorialLesson);tutorialLesson="";tutorialUnit="";tutorialPanel.Visible=false;}
 }
 void ShowTutorial(string id,string message){
  tutorialLesson=id;tutorialUnit=selected?.Id??"";tutorialPanel.Position=new Vector2(150,selected?.Position.Y>=6?145:665);tutorialText.Text=$"CAPTAIN JEANE GERSON\n\n“{message}”";tutorialPanel.Visible=true;
 }
 void UpdateTutorial(){
  if(!settings.Tutorial||b.Mission!=1||b.Finished){tutorialPanel.Visible=false;return;}
  var prior=tutorialLesson;CompleteTutorialLesson();if(prior!=""&&tutorialLesson=="")return;
  if(tutorialLesson!=""){tutorialPanel.Position=new Vector2(150,selected?.Position.Y>=6?145:665);return;}
  if(!tutorialLessons.Contains("move")){ShowTutorial("move","Xander, take point—but don’t outrun your cover. Select a cyan space to move. You can undo the move until you take an action.");return;}
  if(selected?.Role==Role.Shapeshifter&&!tutorialLessons.Contains("nance")&&!selected.Bear){ShowTutorial("nance","Nance can transform into a Bear. She gains health and armor, but loses a little speed. Transform now to prepare her for the front line.");return;}
  if(selected?.Role==Role.Tech&&!tutorialLessons.Contains("akiko")&&b.Robots<3){ShowTutorial("akiko","Akiko can deploy support robots on gold spaces beside her. Robots can scout, attack, and shield the crew. Summon one now.");return;}
  if(selected!=null&&!selected.Moved&&!tutorialLessons.Contains("high-ground")&&b.Reach(selected).Keys.Any(c=>b.TerrainAt(c).Kind==TerrainKind.Elevated)){ShowTutorial("high-ground","The raised cargo is high ground. Climbing costs two extra movement points. From above, ranged attacks deal two extra damage and shots from below deal one less.");return;}
  if(selected!=null&&!selected.Acted&&!tutorialLessons.Contains("low-cover")&&selected.Weapons.Where(w=>w.Range>1).Any(w=>b.Units.Any(e=>e.Alive&&e.Team==Team.Enemy&&b.Range(selected,e.Position,w)&&b.HasLowCover(selected.Position,e.Position)))){ShowTutorial("low-cover","Low crates block movement but not gunfire. When a shot crosses one, the target takes one less ranged damage.");return;}
  if(selected!=null&&!selected.Acted&&!tutorialLessons.Contains("attack")&&selected.Weapons.Any(w=>b.Units.Any(e=>e.Alive&&e.Team==Team.Enemy&&b.Range(selected,e.Position,w)))){ShowTutorial("attack","You have an enemy in range. Choose an attack, then select the enemy. Close-range attacks usually hit harder; Nance chooses between damage and stun.");return;}
  if(selected!=null&&!tutorialLessons.Contains("console")&&!b.ConsoleUsed&&selected.Hero&&selected.Position.Distance(b.Console)<=1){ShowTutorial("console","That console can disrupt a droid for one turn. Use Interact if the temporary opening will help the squad.");return;}
  if(selected!=null&&!tutorialLessons.Contains("rescue")&&selected.Hero&&selected.Position.Distance(b.Issac.Position)==1){ShowTutorial("rescue","You’ve reached Issac. Use Rescue to free him and complete the mission.");}
 }
 string DamagePreviewText(Unit attacker,Unit target,Weapon attack){var d=b.PreviewDamageBreakdown(attacker,target,attack);var detail=d.ModifierSummary.Length>0?$" [{d.ModifierSummary}]":"";return $"{target.Name} {d.FinalDamage} damage{detail} ({target.Hp} → {Math.Max(0,target.Hp-d.FinalDamage)} HP)";}
 string TerrainTip(Cell cell)=>b.TerrainAt(cell).Kind switch{TerrainKind.Wall=>"SOLID WALL • Blocks movement and gunfire.",TerrainKind.Pillar=>"SOLID PILLAR • Blocks movement and gunfire.",TerrainKind.LowCover=>"LOW CRATE • Blocks movement. Crossed ranged attacks deal 1 less damage.",TerrainKind.Elevated=>"HIGH GROUND • Costs 2 extra movement to climb. +2 ranged damage downward; -1 ranged damage from below.",_=>"OPEN FLOOR • Normal movement; does not block gunfire."};
 string ActionTip(string text){
  foreach(var w in selected?.Weapons??[]){if(text.StartsWith(w.Name)){var effect=w.StunOnly?"Deals no HP damage; stuns an ordinary target for its next turn. Ompok’s proxy is immune.":w.Stun?"Damages the target and stuns it for its next turn. Ompok’s proxy cannot be stunned.":"Deals deterministic damage reduced by the target’s armor.";return $"{w.Name}: power {w.Power+((selected?.Level??1)-1)}, range {w.Range}. {effect} Using it ends this unit’s action.";}}
  if(text.StartsWith("Move"))return "Choose any highlighted cyan tile within this unit’s movement allowance. Moving does not spend the unit’s action.";
  if(text.StartsWith("Undo"))return "Return to the space where this unit began its turn so you can choose a different move.";
  if(text.StartsWith("Transform"))return "Nance becomes a Bear, gaining 6 maximum HP and 2 armor, losing 1 movement, and gaining Bear claws and Maul. This uses her action.";
  if(text.StartsWith("Return to human"))return "Nance returns to human form and regains her ranged Pulse palm. She must have more than 6 HP. This uses her action.";
  if(text.StartsWith("Field treatment"))return "Heal an adjacent injured organic teammate for 7 HP. Chrandy cannot heal himself and carries three supplies per mission.";
  if(text.StartsWith("Repair"))return "Restore HP to an adjacent allied robot or reprogrammed droid. Akiko repairs 6 HP; Issac may repair more with Master Mechanic.";
  if(text.StartsWith("Reprogram"))return "Convert an adjacent enemy droid at half health or lower to your side. It becomes available next round.";
  if(text.StartsWith("Summon"))return "Deploy a support robot on a highlighted gold space beside Akiko. Up to three may be active.";
  if(text.StartsWith("Rescue"))return "Free an adjacent captured ally. This uses the rescuer’s action.";
  if(text.StartsWith("Trigger maintenance trap"))return "Use a nearby maintenance control to deal 6 damage and stun the closest enemy.";
  if(text.StartsWith("Run back"))return "Tiger runs toward the nearest uncaptured twin and uses his turn.";
  if(text.StartsWith("Bark"))return "Tiger makes noise and rushes toward an enemy, drawing enemy attention.";
  if(text.StartsWith("Board evacuation"))return "Move Issac into the evacuation shuttle and complete Mission 2.";
  if(text.StartsWith("Interact"))return "Use the nearby objective or console. A console disables one enemy droid for a turn.";
  if(text.StartsWith("Wait"))return "Finish this unit’s turn without taking another action.";
  return text;
 }
