 bool AutoAttack(Unit attacker,Unit target){if(attacker.Role==Role.Medic&&target.Role==Role.OmpokProxy){b.Note("Ompok’s mechanical proxy is immune to Chrandy’s stun pistol.");return false;}if(attacker.Role==Role.Shapeshifter){b.Note("Nance has multiple tactical attacks. Choose Bear claws or Maul, then click the enemy.");mode="attack";return false;}var choices=attacker.Weapons.Select((w,i)=>(w,i)).Where(x=>b.Range(attacker,target.Position,x.w)).ToList();if(choices.Count==0){b.Note($"{target.Name} is not in attack range.");return false;}var adjacent=attacker.Position.Distance(target.Position)==1;var best=choices.Where(x=>adjacent?x.w.Range==1:x.w.Range>1).OrderByDescending(x=>b.PreviewDamage(attacker,target,x.w)).FirstOrDefault();if(best.w==null)best=choices.OrderByDescending(x=>b.PreviewDamage(attacker,target,x.w)).First();return BeginPlayerAttack(attacker,target,best.i);}
